SELECT DISTINCT A.AI_INPT_MENU_ID , A.AI_INPT_MENU_NM , A.AI_INPT_MENU_URL_NM , A.AI_INPT_HGRN_MENU_ID , B.AI_INPT_MENU_NM AS HIGH_NM , A.AI_INPT_MENU_NO , ( SELECT AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = 165 AND AI_INPT_CMN_CD = A.AI_INPT_MENU_NO ) AS SCREEN_NAME , A.AI_INPT_MGPE_YN FROM CSPD108TI A , CSPD108TI B WHERE A.AI_INPT_HGRN_MENU_ID = B.AI_INPT_MENU_ID(+) AND A.AI_INPT_HGRN_MENU_ID IN ( SELECT AI_INPT_MENU_ID FROM CSPD108TI WHERE AI_INPT_HGRN_MENU_ID = #{aiInptHgrnMenuId}
UNION
SELECT #{aiInptHgrnMenuId} AS AI_INPT_MENU_ID FROM DUAL ) ORDER BY AI_INPT_HGRN_MENU_ID, AI_INPT_MENU_NO

